// Fixture batch 184: probes: the parameters of sketch constraints std's features don't use. Generated by tools/fixtures/gen-batch-184.mjs; do not edit.
// Each case builds its geometry at the origin and may return a map of values to check.

function round6(v) returns array
{
    return [roundToPrecision(v[0] / millimeter, 6), roundToPrecision(v[1] / millimeter, 6), roundToPrecision(v[2] / millimeter, 6)];
}

// The sketch's edges' ends and middles, and its points.
function sketchProbe(context is Context, sketchId is Id) returns map
{
    var curves = [];
    for (var edge in evaluateQuery(context, qOwnedByBody(qCreatedBy(sketchId, EntityType.BODY), EntityType.EDGE)))
    {
        const ends = evEdgeTangentLines(context, { "edge" : edge, "parameters" : [0, 0.5, 1] });
        curves = append(curves, [round6(ends[0].origin), round6(ends[1].origin), round6(ends[2].origin)]);
    }
    var points = [];
    for (var v in evaluateQuery(context, qBodyType(qCreatedBy(sketchId, EntityType.BODY), BodyType.POINT)))
        points = append(points, round6(evVertexPoint(context, { "vertex" : qOwnedByBody(v, EntityType.VERTEX) })));
    return { "curves" : curves, "points" : points };
}

// sketch: a line at 30° to a fixed one, the angle given as `angle` with `aligned` false
export function c001(context is Context, id is Id)
{
    const s = newSketchOnPlane(context, id + "s", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skLineSegment(s, "l1", { "start" : vector(0, 0) * millimeter, "end" : vector(30, 0) * millimeter });
    skLineSegment(s, "l2", { "start" : vector(0.4, 0.3) * millimeter, "end" : vector(15, 13) * millimeter });
    skConstraint(s, "fix", { "constraintType" : ConstraintType.FIX, "localFirst" : "l1" });
    skConstraint(s, "co", { "constraintType" : ConstraintType.COINCIDENT, "localFirst" : "l1.start", "localSecond" : "l2.start" });
    skConstraint(s, "a", { "constraintType" : ConstraintType.ANGLE, "localFirst" : "l1", "localSecond" : "l2", "angle" : 30 * degree, "aligned" : false });
    skConstraint(s, "len", { "constraintType" : ConstraintType.LENGTH, "localFirst" : "l2", "length" : 20 * millimeter });
    skSolve(s);
    return sketchProbe(context, id + "s");
}

